function brounhall_seed_doctor( $doctor ) {
	$post = get_page_by_path( $doctor['slug'], OBJECT, 'bh_doctor' );
	$id = $post ? $post->ID : wp_insert_post( array( 'post_type' => 'bh_doctor', 'post_status' => 'publish', 'post_title' => $doctor['name'], 'post_name' => $doctor['slug'], 'menu_order' => $doctor['order'] ) );
	if ( is_wp_error( $id ) || ! $id ) { return 0; }
	if ( ! $post ) { update_post_meta( $id, '_brounhall_doctor_data', wp_json_encode( brounhall_normalize_doctor_data( $doctor ), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES ) ); }
	return (int) $id;
}

